package run.ikaros.document; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException;
@Service public class PersistentDocumentEmbedService implements DocumentEmbedService{private final DocumentRepository documents;private final DocumentEmbedRepository embeds;public PersistentDocumentEmbedService(DocumentRepository d,DocumentEmbedRepository e){documents=d;embeds=e;}@Override public Mono<DocumentEmbedView> create(UUID o,UUID id,CreateDocumentEmbedRequest r){return owned(o,id).then(embeds.save(new DocumentEmbedEntity(null,id,r.attachmentId(),r.displayName(),r.caption(),r.altText(),Instant.now()))).map(this::view);}@Override public Flux<DocumentEmbedView> list(UUID o,UUID id){return owned(o,id).flatMapMany(d->embeds.findAllByDocumentIdOrderByCreatedAtAsc(id).map(this::view));}@Override public Mono<Void> delete(UUID o,UUID id){return embeds.findById(id).switchIfEmpty(Mono.error(new NotFoundException("Document Embed 不存在"))).flatMap(e->owned(o,e.documentId()).then(embeds.delete(e)));}private Mono<DocumentEntity> owned(UUID o,UUID id){return documents.findById(id).filter(d->d.ownerId().equals(o)).switchIfEmpty(Mono.error(new NotFoundException("Document 不存在或无权访问")));}private DocumentEmbedView view(DocumentEmbedEntity e){return new DocumentEmbedView(e.id(),e.documentId(),e.attachmentId(),e.displayName(),e.caption(),e.altText(),e.createdAt());}}
